data "aws_ami" "ubuntu_image" {
  owners      = ["amazon"]
  most_recent = true

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-*-amd64-server-*"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_key_pair" "cg-ec2-key-pair" {
  key_name = "cg-ec2-key-pair-${var.cgid}"
  public_key = file(var.ssh-public-key-for-ec2)
}

resource "aws_iam_instance_profile" "cg-ec2-instance-profile" {
  name = "cg-david_profile"
  role = aws_iam_role.cg-ec2-admin-role.name
}

resource "aws_instance" "cg-ec2-instance" {
  ami                  = data.aws_ami.ubuntu_image.id
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.cg-ec2-instance-profile.name
  key_name             = aws_key_pair.cg-ec2-key-pair.key_name
  subnet_id            = aws_subnet.cg-subnet-1.id
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }
  vpc_security_group_ids = [
    aws_security_group.cg-ec2-ssh-security-group.id,
  ]
  tags        = {
      Name = "cg-david-${var.cgid}"
  }

  depends_on = [aws_db_instance.cg-rds-db_instance]

  provisioner "file" {
    source      = "../assets/insert_data.sql"
    destination = "/home/ubuntu/insert_data.sql"
    connection {
      type        = "ssh"
      user        = "ubuntu"
      private_key = file(var.ssh-private-key-for-ec2)
      host        = self.public_ip
    }
  }

  // https://developer.hashicorp.com/terraform/language/v1.5.x/resources/provisioners/remote-exec
  provisioner "remote-exec" {
  inline = [
    "sudo apt-get update -y",
    "sudo apt install python3-pip -y",
    "pip3 install --upgrade pip",
    "pip3 install awscli --upgrade --user",
    "sudo apt-get install mysql-client -y",
    "cd /home/ubuntu",
    "mysql -h ${aws_db_instance.cg-rds-db_instance.address} -u ${var.rds-username} -p${var.rds-password} < /home/ubuntu/insert_data.sql",
    "sudo rm /home/ubuntu/insert_data.sql"
  ]

  connection {
    type        = "ssh"
    user        = "ubuntu"
    private_key = file(var.ssh-private-key-for-ec2)
    host        = self.public_ip
    }
  }
}

resource "aws_iam_user" "cg-david" {
  name = "cg-rds-instance-user-${var.cgid}"
  tags = {
    Name     = "cg-rds-instance-user-${var.cgid}"
  }
}

resource "aws_iam_access_key" "cg-david" {
  user = aws_iam_user.cg-david.name
}

resource "aws_iam_user_policy" "cg-david-policy" {
  name = "cg-david-policy"
  user = aws_iam_user.cg-david.name

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "rds:DescribeDBInstances",
        "rds:AddTagsToResource",
        "rds:DescribeDBSnapshots",
        "rds:RestoreDBInstanceFromDBSnapshot",
        "rds:ModifyDBInstance",
        "iam:Get*",
        "iam:List*"
      ],
      "Resource": "*"
    }
  ]
}
EOF
}

resource "aws_iam_role" "cg-ec2-admin-role" {
  name = "cg-ec2-admin-role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "cg-ec2-admin-policy" {
  name = "cg-ec2-admin-policy"
  role = aws_iam_role.cg-ec2-admin-role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
                "s3:*",
                "iam:List*",
                "iam:Get*"
            ],
      "Resource": "*"
    }
  ]
}
EOF
}

output "ec2_IP"{
value = "${aws_instance.cg-ec2-instance.public_ip}"
}

output "ssh_command" {
  value = "ssh -i ${var.cgid}/cloudgoat ubuntu@${aws_instance.cg-ec2-instance.public_ip}"
}

output "cloudgoat_output_aws_account_id" {
  value = "${data.aws_caller_identity.aws-account-id.account_id}"
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

// https://registry.terraform.io/providers/hashicorp/aws/5.0.0/docs/resources/db_instance
resource "aws_db_instance" "cg-rds-db_instance" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "5.7"
  instance_class       = "db.t3.micro"
  identifier           = "cg-rds"
  username             = var.rds-username
  password             = var.rds-password
  parameter_group_name = "default.mysql5.7"

  skip_final_snapshot = true

  db_subnet_group_name = aws_db_subnet_group.cg-db-subnet-group.name

  vpc_security_group_ids = [aws_security_group.allow_mysql.id]

  publicly_accessible = false

  tags = {
    Name = "cg-rds-db_instance-${var.cgid}"
  }
}

// https://registry.terraform.io/providers/hashicorp/aws/5.0.0/docs/resources/db_snapshot
resource "aws_db_snapshot" "cg-rds_snapshot" {
  db_instance_identifier = aws_db_instance.cg-rds-db_instance.identifier
  db_snapshot_identifier = "cg-rds-snapshot"

  depends_on = [aws_instance.cg-ec2-instance]

  tags = {
    Name = "cg-rds_snapshot-${var.cgid}"
  }
}

locals {
  bucket_suffix = replace(var.cgid, "/[^a-z0-9-.]/", "-")
}

resource "aws_s3_bucket" "cg-data-s3-bucket" {
  bucket        = "cg-data-s3-bucket-${local.bucket_suffix}"
  force_destroy = true
  tags = {
    Name        = "cg-data-s3-bucket-${local.bucket_suffix}"
    Description = "CloudGoat ${var.cgid} S3 Bucket used for storing a Data"
  }
}

resource "aws_s3_object" "object" {
  bucket = aws_s3_bucket.cg-data-s3-bucket.id
  key    = "access_keys.txt"
  content = "Access Key: ${aws_iam_access_key.cg-david.id}, Secret Key: ${aws_iam_access_key.cg-david.secret}"
}

variable "profile" {
  description = "The AWS profile to use."
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
  type        = string
}

#SSH Public Key
variable "ssh-public-key-for-ec2" {
  default = "../cloudgoat.pub"
}
#SSH Private Key
variable "ssh-private-key-for-ec2" {
  default = "../cloudgoat"
}
variable "cgid" {
  description = "CGID variable for unique naming."
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address"
  type        = list(any)
}

variable "rds-username" {
  description = "RDS Mysql instance username"
  default     = "cgadmin"
  type        = string
}

variable "rds-password" {
  description = "RDS Mysql instance password"
  default     = "cgoat9562!"
  type        = string
}

variable "stack-name" {
  description = "Name of the stack."
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario."
  default     = "rds_snapshot"
  type        = string
}

resource "aws_vpc" "cg-vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_internet_gateway" "cg-internet-gateway" {
  vpc_id = aws_vpc.cg-vpc.id
}

resource "aws_route_table" "cg-public-subnet-route-table" {
  vpc_id = aws_vpc.cg-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.cg-internet-gateway.id
  }
}

resource "aws_main_route_table_association" "cg-public-subnet-1-route-association" {
  vpc_id = aws_vpc.cg-vpc.id
  route_table_id = aws_route_table.cg-public-subnet-route-table.id
}

resource "aws_security_group" "cg-ec2-ssh-security-group" {
  name        = "cg-ec2-ssh-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over SSH"
  vpc_id      = aws_vpc.cg-vpc.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
}

resource "aws_security_group" "allow_mysql" {
  name        = "allow_mysql"
  description = "Allow inbound traffic on MySQL port"
  vpc_id = aws_vpc.cg-vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = concat([aws_vpc.cg-vpc.cidr_block], var.cg_whitelist)
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "cg-subnet-1" {
  vpc_id = aws_vpc.cg-vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "cg-subnet-2" {
  vpc_id = aws_vpc.cg-vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  map_public_ip_on_launch = true
}

resource "aws_db_subnet_group" "cg-db-subnet-group" {
  name       = "cg-db-subnet-group"
  subnet_ids = [aws_subnet.cg-subnet-1.id, aws_subnet.cg-subnet-2.id]
}
